"""Build the baseline page for the foundations corrections.

Reads the entry texts word for word from POSITIONS.md, the at-issue quotes
word for word from salvage-findings.md, and the house CSS and Select script
from the live page's saved HTML. Writes the page source (no document skeleton).

Usage: gen.py LIVE.html OUT.html RUN.json
"""
import html
import re
import sys

REPO = "/home/user/fortress"
LIVE = sys.argv[1]
OUT = sys.argv[2]
COMMIT = "675d44c10bda84c60b40f7989c7d1a096afd1323"
GH = "https://github.com/palimondo/fortress/blob/" + COMMIT + "/"
POS = "explorations/coordinator/POSITIONS.md"
SAL = "explorations/reviews/foundations/evidence/salvage-findings.md"
CORR = "explorations/reviews/foundations/evidence/corrections/"


def inline(md):
    """Escape, then turn `code` and **bold** into HTML."""
    s = html.escape(md, quote=False)
    s = re.sub(r"`([^`]+)`", r"<code>\1</code>", s)
    s = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", s)
    return s


def curly(md):
    """Straight double quotes around a span become curly ones."""
    return re.sub(r'"([^"]*)"', "“\\1”", md)


pos_lines = open(f"{REPO}/{POS}", encoding="utf-8").read().split("\n")
sal_lines = open(f"{REPO}/{SAL}", encoding="utf-8").read().split("\n")


def entry_line(num):
    for i, line in enumerate(pos_lines, 1):
        if line.startswith(f"- P-{num} **"):
            return i, line
    raise SystemExit(f"P-{num} not found")


def at_issue(lineno):
    line = sal_lines[lineno - 1]
    m = re.search(r"At issue: (.*)$", line)
    return m.group(1) if m else None


def link(path, text, line=None):
    url = GH + path + ("?plain=1#L%d" % line if line else "")
    return f'<a href="{url}">{text}</a>'


# Each finding: (line of its block in salvage-findings.md, label of the block,
# the plain sentence, optional sub-items, the reference text).
PARTS = [
}

TOKEN = re.compile(r"(?:[^\s`]|`[^`]*`)+")


def split_line(num, line):
    """'- P-N **title** body' -> (title, body), both Markdown."""
    line = line[2:] if line.startswith("- ") else line
    m = re.match(r"P-%d \*\*(.+?)\*\* ?(.*)$" % num, line, re.S)
    if not m:
        raise SystemExit(f"P-{num}: the text does not start 'P-{num} **title**'")
    return m.group(1), m.group(2)


def plain(md):
    return md.replace("`", "")


def word_diff(old, new):
    """HTML of new against old: <ins> for added words; an empty
    <del data-old="..."> where words were removed, which CSS shows struck
    through and which a selection, so Speak, leaves out."""
    a, b = TOKEN.findall(old), TOKEN.findall(new)
    out = []
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if op == "equal":
            out.append(inline(" ".join(b[j1:j2])))
            continue
        if op in ("delete", "replace"):
            out.append('<del data-old="%s"></del>' % html.escape(plain(" ".join(a[i1:i2])), quote=True))
        if op in ("insert", "replace"):
            out.append("<ins>%s</ins>" % inline(" ".join(b[j1:j2])))
    return " ".join(out)


def text_html(num, title, body):
    return f"P-{num} <strong>{title}</strong> {body}"


def render_findings(num, refs):
    out = ['<h4 class="label">Findings on the current text</h4>', '<ol class="findings">']
    for k, (sline, label, sentence, subs, ref) in enumerate(FINDINGS[num], 1):
        issue = at_issue(sline)
        li = ["<li>"]
        if issue:
            li.append(f'<p class="at-issue">At issue: <span class="quote">{inline(curly(issue))}</span></p>')
        li.append(f"<p>{inline(curly(sentence))}</p>")
        if subs:
            li.append("<ul>" + "".join(f"<li>{inline(curly(s))}</li>" for s in subs) + "</ul>")
        li.append("</li>")
        out.append("".join(li))
        refs.append(f'<li>P-{num}, finding {k}: {link(SAL, "the findings list, block " + label, sline)}; {ref}</li>')
    out.append("</ol>")
    return out


def render_correction(c, refs):
    num = int(c["num"][2:])
    lineno, line = entry_line(num)
    title, body = split_line(num, line)
    ntitle, nbody = split_line(num, c["text"])
    out = [f'<section class="part entry" id="p-{num}">']
    out.append(f'<h3><span class="num">P-{num}</span>{inline(HANDLES[num])}</h3>')
    out.append('<h4 class="label">The new text</h4>')
    out.append('<div class="entry-text diff"><p>' + text_html(num, word_diff(title, ntitle), word_diff(body, nbody)) + "</p></div>")
    out.append('<details class="old"><summary>The current text</summary><p>' + text_html(num, inline(title), inline(body)) + "</p></details>")
    out.append('<div class="reasons">')
    out.append('<h4 class="label">What changed and why</h4>')
    out.append(f'<p class="run-did">{inline(curly(c["why"]))}</p>')
    refs.append(f'<li>P-{num}, its current text: {link(POS, "POSITIONS.md line %d" % lineno, lineno)}, unchanged since commit <code>5da8144e4</code> of 26 October; its new text and what changed: {link(FINAL + "changes.md", "<code>changes.md</code>")}, section P-{num}.</li>')
    if num in FINDINGS:
        out += render_findings(num, refs)
    out.append("</div>")
    out.append("</section>")
    return "\n".join(out)


FINAL = CORR + "final/"

live = open(LIVE, encoding="utf-8").read()
css = re.search(r"(<style>\n:root \{.*?</style>)", live, re.S).group(1)
fonts = re.search(r'(<link rel="preconnect".*?\n<link rel="stylesheet"[^\n]*>)', live, re.S).group(1)

# The house Select script, with two changes for sections inside sections:
# each section takes its own heading and its own end mark (direct children
# only), and the selection also ends before an entry's collapsed text and its
# reasons, so that Speak reads the new text alone.
script = """<script>
document.querySelectorAll('section.part').forEach(function (sec) {
  var h = sec.querySelector(':scope > h2, :scope > h3');
  if (!h) return;
  var b = document.createElement('button');
  b.type = 'button';
  b.className = 'sel';
  b.setAttribute('aria-label', 'Select this section to have it read aloud');
  h.appendChild(b);
  b.addEventListener('click', function (e) {
    e.preventDefault();
    var r = document.createRange();
    r.setStart(h, 0);
    var src = sec.querySelector(':scope > details.old, :scope > .reasons, :scope > .sources');
    if (src) r.setEndBefore(src); else r.setEnd(sec, sec.childNodes.length);
    var sel = window.getSelection();
    sel.removeAllRanges();
    sel.addRange(r);
  });
});
</script>"""

page_css = """<style>
.entry-text { border-left: 3px solid var(--accent); padding-left: .7rem; }
details.old { border-left: 3px solid var(--rule); padding-left: .7rem; margin: .6rem 0 .8rem; }
details.old summary { cursor: pointer; color: var(--muted); font-weight: 700; margin-bottom: .5rem; }
nav.parts li > p { margin: .2rem 0 .3rem; }
nav.parts .nums { font-family: var(--mono); font-size: .86rem; }
section.part.entry { border-top: 1px dashed var(--rule); padding-top: 14px; margin-top: 22px; }
section.part h3 { margin: 0 0 .5rem; }
section.part h3 .num { display: block; font-family: var(--mono); font-size: .78rem; font-weight: 600; color: var(--accent); letter-spacing: .02em; }
h4.label { font-family: var(--mono); font-size: .76rem; font-weight: 600; letter-spacing: .04em; color: var(--muted); margin: .9rem 0 .4rem; }
ins { text-decoration: underline; text-decoration-color: var(--accent); text-decoration-thickness: 2px; background: var(--code-bg); }
del[data-old]::before { content: attr(data-old); text-decoration: line-through; color: var(--muted); }
